        s += '<text x="' + (x0 + 2.8 * sx).toFixed(1) + '" y="' + (y0 - 8.3 * sy).toFixed(1) + '" font-family="sans-serif" font-size="15" font-weight="bold" fill="#1971c2">y = 2ˣ</text>';

