        els.push(shape('ellipse', cx - 9, y - 9, 18, 18, { fill: i === o.hl ? 'brand' : 'title' }));
        els.push(T(cx - 45, y + 12, 90, 36, v, { size: o.size || 26, color: i === o.hl ? 'brand' : 'title', align: 'center' }));
