        s += '<circle cx="' + (cx + sx).toFixed(1) + '" cy="' + (cy - Math.PI / 2 * sy).toFixed(1) + '" r="5" fill="#1971c2"/>';
        s += '<circle cx="' + (cx - sx).toFixed(1) + '" cy="' + (cy + Math.PI / 2 * sy).toFixed(1) + '" r="5" fill="#1971c2"/>';
